def test_ss01_negative_no_retry_on_401():
    def should_retry(status):
        return status >= 500
    assert should_retry(500) is True
    assert should_retry(401) is False

def test_ss01_boundary_backoff_floor():
    def backoff(attempt):
        return max(100, 50 * (2 ** attempt))
    assert backoff(0) == 100
    assert backoff(3) >= 100

def test_ss02_compositional_pipeline():
    def pipe(items):
        return [x * 2 for x in items if x > 0]
    assert pipe([-1, 1, 2, 3]) == [2, 4, 6]

def test_ss02_negative_rejects_bad_element():
    def pipe(items):
        out = []
        for x in items:
            if not isinstance(x, int):
                raise ValueError('bad element')
            out.append(x)
        return out
    try:
        pipe([1, 'x'])
    except ValueError:
        pass
    else:
        raise AssertionError('expected ValueError')

def test_ss02_boundary_empty_input():
    def pipe(items):
        return [x * 2 for x in items if x > 0]
    assert pipe([]) == []
